
#pragma once

#include "carla/Debug.h"
#include "carla/Memory.h"
#include "carla/sensor/RawData.h"
#include "carla/sensor/data/SemanticRadarData.h"

namespace carla {
namespace sensor {

class SensorData;

namespace s11n {

  // ===========================================================================
  // -- SemanticRadarSerializer ------------------------------------------------
  // ===========================================================================

  /// Serializes the data generated by Radar sensors.
  class SemanticRadarSerializer {
  public:

    template <typename Sensor>
    static Buffer Serialize(
        const Sensor &sensor,
        const data::SemanticRadarData &measurement,
        Buffer &&output);

    static SharedPtr<SensorData> Deserialize(RawData &&data);
  };

  template <typename Sensor>
  inline Buffer SemanticRadarSerializer::Serialize(
      const Sensor &,
      const data::SemanticRadarData &measurement,
      Buffer &&output) {
    output.copy_from(measurement._detections);
    return std::move(output);
  }

} // namespace s11n
} // namespace sensor
} // namespace carla